declarations:
interface AppliedMigration {
    readonly packageId: string;
    readonly name: string;
    readonly durationMs: number;
}

interface Finding {
    readonly severity: Severity;
    readonly line: number;
    readonly reason: string;
    readonly text: string;
}

interface LoadedMigrations {
    readonly migrations: readonly Migration[];
    readonly problems: readonly MigrationProblem[];
}

type MigrateFailure = {
    readonly kind: 'invalid';
    readonly problems: readonly MigrationProblem[];
} | {
    readonly kind: 'lock-timeout';
    readonly message: string;
} | {
    readonly kind: 'ledger-mismatch';
    readonly problems: readonly MigrationProblem[];
} | {
    readonly kind: 'ledger-too-new';
    readonly message: string;
} | {
    readonly kind: 'session-not-pinned';
    readonly message: string;
} | {
    readonly kind: 'dirty';
    readonly migrations: readonly string[];
    readonly message: string;
} | {
    readonly kind: 'migration-failed';
    readonly packageId: string;
    readonly name: string;
    readonly sqlState: string | undefined;
    readonly message: string;
    readonly applied: readonly AppliedMigration[];
};

interface MigrateOptions {
    readonly connectionString: string;
    readonly sources: readonly MigrationSource[];
    readonly runLockTimeoutMs?: number;
    readonly migrationLockTimeoutMs?: number;
    readonly statementTimeoutMs?: number;
    readonly release?: string;
    readonly dryRun?: boolean;
}

interface MigrateReport {
    readonly applied: readonly AppliedMigration[];
    readonly pending: readonly Pick<Migration, 'packageId' | 'name'>[];
    readonly alreadyApplied: number;
}

interface Migration {
    readonly packageId: string;
    readonly name: string;
    readonly number: number;
    readonly file: string;
    readonly sql: string;
    readonly checksum: string;
    readonly phase: Phase;
    readonly transactional: boolean;
    readonly reason?: string;
    readonly securityReview?: string;
}

interface MigrationProblem {
    readonly rule: ProblemRule;
    readonly migration?: string;
    readonly file?: string;
    readonly line?: number;
    readonly message: string;
}

interface MigrationSource {
    readonly packageId: string;
    readonly dir: string;
    readonly depends: readonly string[];
    readonly displayDir: string;
}

interface Statement {
    readonly code: string;
    readonly line: number;
}

declare function forgetStarted(connectionString: string, migration: string): Promise<Result<undefined, {
    readonly message: string;
}>>;
